class Solution {
public:
    int minOperations(vector<int>& nums1, vector<int>& nums2) {
        int n = nums1.size();
        auto check = [&](int t1, int t2) -> int {
            int cost = 0;
            for (int i = 0; i < n - 1; i++) {
                if (nums1[i] <= t1 && nums2[i] <= t2) continue;
                else if (nums2[i] <= t1 && nums1[i] <= t2) cost++;
                else return 1e9;
            }
            return cost;
        };
        int c1 = check(nums1[n - 1], nums2[n - 1]);
        int c2 = check(nums2[n - 1], nums1[n - 1]) + 1;
        int ans = min(c1, c2);
        return ans >= 1e9 ? -1 : ans;
    }
};

class Solution {
    public int minOperations(int[] nums1, int[] nums2) {
        int n = nums1.length;
        int c1 = check(nums1, nums2, nums1[n - 1], nums2[n - 1]);
        int c2 = check(nums1, nums2, nums2[n - 1], nums1[n - 1]);
        if (c2 != Integer.MAX_VALUE) c2 += 1;
        int ans = Math.min(c1, c2);
        return ans >= 1_000_000 ? -1 : ans;
    }
    int check(int[] nums1, int[] nums2, int t1, int t2) {
        int cost = 0;
        for (int i = 0; i < nums1.length - 1; i++) {
            if (nums1[i] <= t1 && nums2[i] <= t2) continue;
            else if (nums2[i] <= t1 && nums1[i] <= t2) cost++;
            else return 1_000_000;
        }
        return cost;
    }
}

